func TestConvertToDistroAdvisoryRejectsUnsupportedTitles(t *testing.T) {
	for _, tc := range []struct{ family, title, want string }{
		{constant.RedHat, \"RHSA-2024:1234: security update\", \"RHSA-2024:1234\"},
		{constant.RedHat, \"RHBA-2024:1234: bug fix\", \"RHBA-2024:1234\"},
		{constant.CentOS, \"RHSA-2024:1234: security update\", \"RHSA-2024:1234\"},
		{constant.Alma, \"RHSA-2024:1234: security update\", \"RHSA-2024:1234\"},
		{constant.Rocky, \"RHSA-2024:1234: security update\", \"RHSA-2024:1234\"},
		{constant.Oracle, \"ELSA-2024-1234: security update\", \"ELSA-2024-1234\"},
		{constant.Amazon, \"ALAS2-2024-1234\", \"ALAS2-2024-1234\"},
		{constant.Fedora, \"FEDORA-2024-1234\", \"FEDORA-2024-1234\"},
		{constant.RedHat, \"CVE-2024-1234: affected package\", \"\"},
		{constant.Oracle, \"RHSA-2024:1234: security update\", \"\"},
		{constant.Fedora, \"\", \"\"},
	} {
		got := (RedHatBase{Base: Base{family: tc.family}}).convertToDistroAdvisory(&ovalmodels.Definition{Title: tc.title})
		if tc.want == \"\" {
			if got "'!= nil { t.Errorf("%s %q: got advisory %q", tc.family, tc.title, got.AdvisoryID) }
		} else if got == nil || got.AdvisoryID != tc.want {
			t.Errorf("%s %q: got %v, want %q", tc.family, tc.title, got, tc.want)
		}
	}
}
EOF
